WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_age_d_constant'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '年龄差恒定', 'kp-age-d-constant', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "年龄差恒定定律"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "铁律：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "无论时光怎么流逝，甲比乙大几岁，这个数字永远是一个死数！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“5 年前，哥哥比弟弟大 8 岁。3 年后，哥哥的年龄是弟弟的 2 倍……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "看到“大 x 岁”、“小 y 岁”，立刻把这个差值锁定。这是贯穿过去现在未来的锚点。"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{任何时刻：} \\quad Age_{大} - Age_{小} = \\Delta \\text{(常数)}"}}]}$$ AS jsonb), NULL, '年龄差恒定的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "年龄差恒定"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_d_constant", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
